from __future__ import annotations

import csv
import json
import math
import re
from datetime import datetime, timedelta, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATASET_DIR = Path("/app/dataset")
REPORT_START = datetime(2024, 3, 15, 0, 0, 0)
REPORT_END = datetime(2024, 3, 16, 0, 0, 0)
TIMESTAMP_FORMATS = ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S")
UNIT_TO_KWH = {
    "kwh": 1.0,
    "wh": 1.0 / 1000.0,
    "mwh": 1000.0,
    "btu": 0.00029307107,
}


def parse_timestamp(value: object) -> datetime | pd.NaT:
    text = str(value).strip()
    if not text:
        return pd.NaT
    for fmt in TIMESTAMP_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    return pd.NaT


def parse_number(value: object) -> float:
    text = str(value).strip()
    if not text:
        return math.nan
    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(",", ".")
    try:
        return float(text)
    except ValueError:
        return math.nan


def detect_encoding(path: Path) -> str:
    raw = path.read_bytes()
    return "utf-16" if b"\x00" in raw[:200] else "utf-8"


def read_production_frame(path: Path) -> tuple[pd.DataFrame, list[str]]:
    text = path.read_text(encoding=detect_encoding(path))
    lines = text.splitlines()
    header_idx = next(
        idx for idx, line in enumerate(lines) if line.strip().lower().startswith("timestamp")
    )
    delimiter = ";" if ";" in lines[header_idx] else ","
    rows = list(csv.reader(lines[header_idx:], delimiter=delimiter))
    columns = rows[0]
    data_rows = rows[1:]
    return pd.DataFrame(data_rows, columns=columns), columns


def normalize_unit(unit: str) -> str:
    return "".join(ch.lower() for ch in unit if ch.isalpha())


def load_sensor_config() -> dict[str, dict]:
    payload = json.loads((DATASET_DIR / "sensors_calibration.json").read_text())
    return payload["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def load_farm_metadata() -> dict[str, dict]:
    farms = pd.read_csv(DATASET_DIR / "farms.csv")
    registry = pd.read_csv(DATASET_DIR / "farm_registry.csv")
    farms["farm_name_norm"] = farms["farm_name"].astype(str).str.strip().str.casefold()
    registry["farm_name_norm"] = registry["farm_name"].astype(str).str.strip().str.casefold()
    merged = registry.merge(
        farms[["farm_name_norm", "timezone", "installed_capacity_kw"]],
        on="farm_name_norm",
        how="left",
    )
    return merged.set_index("farm_id").to_dict("index")


def parse_safety_protocol(notes: str) -> tuple[float, timedelta]:
    match = re.search(
        r"If inverter_temperature_C exceeds (\d+(?:\.\d+)?)C.*?Readings for the (\d+) minutes",
        notes,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not match:
        return 85.0, timedelta(minutes=45)
    threshold_c = float(match.group(1))
    duration = timedelta(minutes=int(match.group(2)))
    return threshold_c, duration


def parse_maintenance_windows(farm_metadata: dict[str, dict]) -> dict[str, list[tuple[datetime, datetime]]]:
    notes = (DATASET_DIR / "maintenance_notes.txt").read_text()
    windows_by_farm: dict[str, list[tuple[datetime, datetime]]] = {}
    name_to_farm_id = {
        info["farm_name_norm"]: farm_id for farm_id, info in farm_metadata.items()
    }

    for line in notes.splitlines():
        if "status: completed" not in line.casefold():
            continue

        match = re.search(
            r" on (.+?) on the (\d+)(?:st|nd|rd|th) of March from (\d{2}:\d{2}) to (\d{2}:\d{2}) local time\.",
            line,
            flags=re.IGNORECASE,
        )
        if match:
            farm_name, day, start_time, end_time = match.groups()
        else:
            match = re.search(
                r" at (.+?) on March (\d+), starting at (\d{2}:\d{2}) and finishing at (\d{2}:\d{2}) local time\.",
                line,
                flags=re.IGNORECASE,
            )
            if not match:
                continue
            farm_name, day, start_time, end_time = match.groups()

        farm_name_norm = farm_name.strip().casefold()
        farm_id = name_to_farm_id.get(farm_name_norm)
        if farm_id is None:
            continue

        timezone_name = farm_metadata[farm_id]["timezone"]
        tz = ZoneInfo(timezone_name)
        start_local = datetime(
            2024,
            3,
            int(day),
            int(start_time[:2]),
            int(start_time[3:]),
            tzinfo=tz,
        )
        end_local = datetime(
            2024,
            3,
            int(day),
            int(end_time[:2]),
            int(end_time[3:]),
            tzinfo=tz,
        )
        start_utc = start_local.astimezone(timezone.utc).replace(tzinfo=None)
        end_utc = end_local.astimezone(timezone.utc).replace(tzinfo=None)
        windows_by_farm.setdefault(farm_id, []).append((start_utc, end_utc))

    return windows_by_farm


def apply_shutdown_rule(
    df: pd.DataFrame,
    temp_col: str,
    threshold_c: float,
    cooldown: timedelta,
) -> pd.DataFrame:
    spike_times = df.loc[df[temp_col] > threshold_c, "timestamp_parsed"].tolist()
    if not spike_times:
        return df

    invalid_mask = pd.Series(False, index=df.index)
    for spike_time in spike_times:
        invalid_mask |= (df["timestamp_parsed"] > spike_time) & (
            df["timestamp_parsed"] <= spike_time + cooldown
        )
    return df.loc[~invalid_mask].copy()


def infer_cadence_hours(df: pd.DataFrame) -> float:
    deltas = (
        df["timestamp_parsed"]
        .sort_values()
        .drop_duplicates()
        .diff()
        .dropna()
        .dt.total_seconds()
        .div(3600.0)
    )
    deltas = deltas[deltas > 0]
    if deltas.empty:
        return 0.0
    return float(deltas.mode().iloc[0])


def compute_farm_total(
    farm_id: str,
    sensor_config: dict,
    maintenance_windows: list[tuple[datetime, datetime]],
    safety_threshold_c: float,
    safety_cooldown: timedelta,
) -> int:
    frame, columns = read_production_frame(DATASET_DIR / f"production_{farm_id}.csv")
    frame = frame.drop_duplicates()

    value_col_idx = columns.index(sensor_config["calibration_data"]["value_column_name"])
    frame["timestamp_parsed"] = frame.iloc[:, 0].map(parse_timestamp)
    frame = frame[frame["timestamp_parsed"].notna()].copy()
    frame = frame.sort_values("timestamp_parsed", kind="stable")
    # Duplicate timestamps carry a sentinel row first and the usable row last.
    frame = frame.drop_duplicates(subset=["timestamp_parsed"], keep="last").copy()

    frame["inverter_temperature_C_num"] = frame["inverter_temperature_C"].map(parse_number)
    frame["raw_value"] = frame.iloc[:, value_col_idx].map(parse_number)
    frame = apply_shutdown_rule(
        frame,
        temp_col="inverter_temperature_C_num",
        threshold_c=safety_threshold_c,
        cooldown=safety_cooldown,
    )

    cadence_hours = infer_cadence_hours(frame)
    frame = frame[
        (frame["timestamp_parsed"] >= REPORT_START) & (frame["timestamp_parsed"] < REPORT_END)
    ].copy()
    for window_start, window_end in maintenance_windows:
        frame = frame[
            ~(
                (frame["timestamp_parsed"] >= window_start)
                & (frame["timestamp_parsed"] < window_end)
            )
        ].copy()

    frame = frame[frame["raw_value"].notna()].copy()
    if frame.empty:
        return 0

    calibration_offset = sensor_config["calibration_data"]["calibration_offset"]
    frame["true_value"] = frame["raw_value"] - calibration_offset
    frame = frame[frame["true_value"] >= 0].copy()
    if frame.empty:
        return 0

    reading_type = sensor_config["sensor_info"]["reading_type"].casefold()
    unit = normalize_unit(sensor_config["sensor_info"]["unit"])
    if reading_type == "energy":
        total_kwh = float(frame["true_value"].sum()) * UNIT_TO_KWH[unit]
    else:
        total_kwh = float(frame["true_value"].sum()) * cadence_hours

    return round(total_kwh)


def answer() -> dict[str, int]:
    notes = (DATASET_DIR / "maintenance_notes.txt").read_text()
    safety_threshold_c, safety_cooldown = parse_safety_protocol(notes)
    sensor_config = load_sensor_config()
    farm_metadata = load_farm_metadata()
    maintenance_windows = parse_maintenance_windows(farm_metadata)

    return {
        farm_id: compute_farm_total(
            farm_id=farm_id,
            sensor_config=config,
            maintenance_windows=maintenance_windows.get(farm_id, []),
            safety_threshold_c=safety_threshold_c,
            safety_cooldown=safety_cooldown,
        )
        for farm_id, config in sorted(sensor_config.items())
    }


